// Writes the two generated files the font library feeds, from authoring/fonts/fonts.json and
// metrics.json:
//   authoring/kit/font-data.mjs                          pure-JS facts the look code reads (bundleable)
//   FacebookClone/Bubbles/Runtime/web/game-fonts.css     the @font-face rules the app and Chrome load
//
// Each face's src lists the bundled woff2 first and then local() system faces of the same kind, so
// a font that can't load falls back to the nearest system face, not to the browser default.
//
//   node authoring/kit/make-fonts.mjs [--check]     (--check: exit 1 if either file is stale)

import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const authoring = join(here, '..');
const root = join(authoring, '..');
const fonts = JSON.parse(readFileSync(join(authoring, 'fonts/fonts.json'), 'utf8')).families;
const metrics = JSON.parse(readFileSync(join(authoring, 'fonts/metrics.json'), 'utf8'));

/** The kind of each family: picks its system fallback faces. */
export const CLASSES = {
  bungee: 'display_sans', monoton: 'geometric', righteous: 'geometric', bowlby: 'display_sans', press_start: 'pixel',
  vt323: 'pixel', silkscreen: 'pixel', creepster: 'hand', dm_serif: 'serif', playfair: 'serif', orbitron: 'geometric',
  unifraktur: 'blackletter', uncial: 'blackletter', cinzel: 'serif', chewy: 'hand', archivo_black: 'display_sans',
  syne: 'geometric', audiowide: 'geometric', michroma: 'geometric', bangers: 'condensed', dela_gothic: 'display_sans',
  teko: 'condensed', alfa_slab: 'slab', rye: 'slab', lobster: 'script', pacifico: 'script', abril: 'serif',
  poiret: 'geometric', special_elite: 'typewriter', oswald: 'condensed', space_mono: 'mono', share_tech_mono: 'mono',
  im_fell: 'serif', cormorant: 'serif', fredoka: 'rounded', baloo: 'rounded', patrick_hand: 'hand', nunito: 'rounded',
  caveat: 'hand', space_grotesk: 'sans', archivo: 'sans', mplus_rounded: 'rounded', barlow_cond: 'condensed',
  lora: 'serif', josefin: 'geometric', courier_prime: 'typewriter', libre_baskerville: 'serif', dm_sans: 'sans',
  work_sans: 'sans', rubik: 'rounded', outfit: 'geometric', barlow_cond_italic: 'condensed',
  // Characterful display faces (art direction v2): titles, HUD numbers and big words only.
  lilita: 'rounded', bagel: 'rounded', shrikhand: 'script', rubik_mono: 'display_sans', luckiest: 'display_sans',
  permanent_marker: 'hand', titan: 'rounded', black_ops: 'display_sans', bungee_shade: 'display_sans', faster: 'display_sans',
  nosifer: 'hand', pirata: 'blackletter', knewave: 'hand', zen_dots: 'geometric', cherry_bomb: 'rounded',
  metal_mania: 'blackletter', boogaloo: 'rounded', racing_sans: 'condensed', sedgwick: 'hand',
};

/** iPhone system faces for each kind, nearest first. */
export const SYSTEM_STACKS = {
  display_sans: ['Futura-CondensedExtraBold', 'AvenirNext-Heavy', 'Futura'],
  geometric: ['Futura-Medium', 'Futura', 'Avenir Next'],
  pixel: ['Menlo-Bold', 'Menlo', 'Courier New'],
  hand: ['ChalkboardSE-Bold', 'Chalkboard SE', 'Noteworthy'],
  serif: ['Baskerville', 'Georgia', 'Times New Roman'],
  blackletter: ['Baskerville-SemiBold', 'Baskerville', 'Georgia'],
  condensed: ['AvenirNextCondensed-Bold', 'Avenir Next Condensed', 'Helvetica Neue'],
  slab: ['Rockwell-Bold', 'Rockwell', 'American Typewriter'],
  script: ['SnellRoundhand-Bold', 'Snell Roundhand', 'Noteworthy'],
  typewriter: ['AmericanTypewriter', 'American Typewriter', 'Courier New'],
  mono: ['Menlo', 'Courier New'],
  rounded: ['ArialRoundedMTBold', 'Arial Rounded MT Bold', 'Avenir Next'],
  sans: ['AvenirNext-Medium', 'Avenir Next', 'Helvetica Neue'],
};

function data() {
  const fams = {};
  for (const [id, f] of Object.entries(fonts)) {
    if (!CLASSES[id]) throw new Error(`no class for font ${id}`);
    const m = metrics[id] ?? {};
    const weights = Object.keys(f.files).map((w) => parseInt(w, 10)).sort((a, b) => a - b);
    const w0 = String(weights[0]);
    fams[id] = {
      family: f.family, role: f.role, cls: CLASSES[id], caps: !!f.caps_only, mono: !!f.mono, weights,
      avg: Object.fromEntries(weights.map((w) => [w, m[w]?.avg ?? 0.55])),
      avgCaps: Object.fromEntries(weights.map((w) => [w, m[w]?.avg_caps ?? 0.62])),
      tabular: !!m[w0]?.digits_tabular, cap: m[w0]?.cap ?? 0.7, x: m[w0]?.x ?? 0.5,
      license: f.license, files: f.files,
    };
  }
  return fams;
}

function css(fams) {
  const out = ['/* Bundled game fonts (subset woff2). Generated by authoring/kit/make-fonts.mjs; see authoring/fonts/README.md. */',
    '/* Each face falls back to the nearest iPhone system face of the same kind when its file can\'t load. */'];
  for (const [id, f] of Object.entries(fams)) {
    const locals = SYSTEM_STACKS[f.cls].map((n) => `local("${n}")`).join(', ');
    const ws = f.weights;
    ws.forEach((w, i) => {
      const range = ws.length === 1 ? '100 900' : i === 0 ? '100 599' : '600 900';
      out.push('@font-face {', `  font-family: "${f.family}";`, `  src: url("${f.files[w] ?? f.files[`${w}i`]}") format("woff2"), ${locals};`,
        `  font-weight: ${range};`, '  font-style: normal;', '  font-display: block;', '}');
    });
  }
  return out.join('\n') + '\n';
}

const fams = data();
const js = `// Generated by authoring/kit/make-fonts.mjs from authoring/fonts/fonts.json and metrics.json. Don't edit.
// Per family: CSS family name, role, kind (system fallback), caps-only, monospaced, weights shipped,
// average advance (em) per weight for mixed case and for capitals, tabular digits, cap and x height.
// Pure JS (the Studio bundle packs it).

export const FONT_DATA = ${JSON.stringify(Object.fromEntries(Object.entries(fams).map(([id, f]) => [id, { family: f.family, role: f.role, cls: f.cls, caps: f.caps, mono: f.mono, weights: f.weights, avg: f.avg, avgCaps: f.avgCaps, tabular: f.tabular, cap: f.cap, x: f.x }])), null, 0).replace(/\},"/g, '},\n  "').replace(/^\{/, '{\n  ').replace(/\}$/, ',\n}')};

export const SYSTEM_STACKS = ${JSON.stringify(SYSTEM_STACKS, null, 2)};
`;
const cssText = css(fams);
const jsFile = join(here, 'font-data.mjs');
const cssFile = join(root, 'FacebookClone/Bubbles/Runtime/web/game-fonts.css');
if (process.argv.includes('--check')) {
  const stale = [[jsFile, js], [cssFile, cssText]].filter(([f, t]) => { try { return readFileSync(f, 'utf8') !== t; } catch { return true; } });
  if (stale.length) { console.log('stale:', stale.map(([f]) => f).join(', ')); process.exit(1); }
  console.log('font files up to date');
} else {
  writeFileSync(jsFile, js);
  writeFileSync(cssFile, cssText);
  console.log(`wrote ${Object.keys(fams).length} families: ${jsFile}, ${cssFile}`);
}
